class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(arr):
    if not arr or arr[0] is None:
        return None
    root = TreeNode(arr[0])
    queue = [root]
    i = 1
    while i < len(arr) and queue:
        node = queue.pop(0)
        if i < len(arr):
            left_val = arr[i]
            i += 1
            if left_val is not None:
                node.left = TreeNode(left_val)
                queue.append(node.left)
        if i < len(arr):
            right_val = arr[i]
            i += 1
            if right_val is not None:
                node.right = TreeNode(right_val)
                queue.append(node.right)
    return root


def is_subtree(root_arr, subroot_arr):
    root = build_tree(root_arr)
    sub_root = build_tree(subroot_arr)

    def is_same(a, b):
        if a is None and b is None:
            return True
        if a is None or b is None:
            return False
        return a.val == b.val and is_same(a.left, b.left) and is_same(a.right, b.right)

    def contains(node):
        if node is None:
            return False
        if is_same(node, sub_root):
            return True
        return contains(node.left) or contains(node.right)

    return contains(root)

